?>
<div class="admin-form-wrap"><a class="back-link" href="<?=osis_e(osis_url('admin/pengumuman/index.php'))?>">← Semua pengumuman</a><div class="admin-panel form-panel"><span class="eyebrow">INFORMASI RESMI</span><h2>Pengumuman baru</h2><?php if($error):?><div class="alert alert-error"><?=osis_e($error)?></div><?php endif;?><form method="post" data-validate-form><?=osis_csrf_input()?><label for="judul">Judul</label><input id="judul" name="judul" required maxlength="180" value="<?=osis_e(isset($_POST['judul'])?$_POST['judul']:'')?>"><label for="isi">Isi pengumuman</label><textarea id="isi" name="isi" rows="10" required><?=osis_e(isset($_POST['isi'])?$_POST['isi']:'')?></textarea><label class="check-line"><input type="checkbox" name="penting" value="ya" <?=isset($_POST['penting'])?'checked':''?>> <span>Tandai sebagai pengumuman penting <small>Pengumuman penting ditampilkan paling atas.</small></span></label><div class="form-actions"><a class="button button-outline" href="<?=osis_e(osis_url('admin/pengumuman/index.php'))?>">Batal</a><button class="button button-primary" type="submit">Terbitkan <span>↗</span></button></div></form></div></div>
